const express = require('express');
const app = express();

// IoT Device Message Handler
// Processes telemetry data from connected devices

const DEVICE_ID_PATTERN = /^([a-zA-Z0-9]+[-_]?)+([a-zA-Z0-9]+\.)*[a-zA-Z0-9]+$/;
const FIRMWARE_VERSION_PATTERN = /^(\d+\.)+\d+(-[a-z]+)*$/;
const TOPIC_PATTERN = /^(\/[a-zA-Z0-9_-]+)+(\/\#|\+)?$/;

function validateDeviceMessage(payload) {
  const errors = [];

  if (payload.device_id) {
    if (!DEVICE_ID_PATTERN.test(payload.device_id)) {
      errors.push('Invalid device_id format');
    }
  }

  if (payload.firmware_version) {
    if (!FIRMWARE_VERSION_PATTERN.test(payload.firmware_version)) {
      errors.push('Invalid firmware_version format');
    }
  }

  if (payload.topic) {
    if (!TOPIC_PATTERN.test(payload.topic)) {
      errors.push('Invalid topic format');
    }
  }

  return errors;
}

app.use(express.json({ limit: '1mb' }));

// Device telemetry ingestion endpoint
app.post('/api/v2/devices/telemetry', (req, res) => {
  const { device_id, firmware_version, topic, readings, timestamp } = req.body;

  if (!device_id || !readings) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const validationErrors = validateDeviceMessage(req.body);

  if (validationErrors.length > 0) {
    return res.status(422).json({
      error: 'Validation failed',
      details: validationErrors,
      submitted_device_id: device_id,
      submitted_topic: topic || 'none'
    });
  }

  // Process valid telemetry
  const processed = {
    device_id,
    firmware_version: firmware_version || 'unknown',
    topic: topic || '/default/telemetry',
    readings,
    received_at: new Date().toISOString(),
    server_timestamp: timestamp || Date.now()
  };

  // Store telemetry (simplified)
  console.log(`[TELEMETRY] Device ${device_id}: ${JSON.stringify(readings)}`);

  res.status(201).json({
    status: 'accepted',
    message_id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    device: device_id
  });
});

// Device status dashboard (renders device info)
app.get('/dashboard/device/:id', (req, res) => {
  const deviceId = req.params.id;
  const lastMessage = req.query.last_message || 'No recent messages';

  // Server-side rendered dashboard snippet
  const html = `<!DOCTYPE html>
<html>
<head><title>Device ${deviceId} Status</title></head>
<body>
  <h1>Device Dashboard</h1>
  <div id="device-info">
    <p>Device ID: ${deviceId}</p>
    <p>Last Message: ${lastMessage}</p>
  </div>
  <script>document.getElementById('device-info').style.color='green';</script>
</body>
</html>`;

  res.send(html);
});

app.listen(3000, () => {
  console.log('IoT Gateway running on port 3000');
});
